structure.mermaidSource:
flowchart TD
  start["Início: Oração com verbo no infinitivo"] --> proc_isolar["Isolar o segmento que contém o verbo no infinitivo"]
  proc_isolar --> proc_substituir["Substituir a oração inteira por 'isso' (ou 'disso' / 'nisso')"]
  proc_substituir --> dec_teste_isso{"A oração principal mantém sentido gramatical completo?"}
  dec_teste_isso -- "Não" --> res_nao_substantiva["Não é Subordinada Substantiva (testar Adverbial ou Adjetiva)"]
  dec_teste_isso -- "Sim" --> proc_ordem_direta["Reorganizar período na ordem direta (Sujeito + Verbo + Complementos)"]
  proc_ordem_direta --> dec_sujeito{"Responde a 'O que é que + verbo?' (atua como Sujeito)?"}
  dec_sujeito -- "Sim" --> res_subjetiva["Oração Subordinada Substantiva Subjetiva"]
  dec_sujeito -- "Não" --> dec_pos_ligacao{"Posicionada após Verbo de Ligação vinculada ao Sujeito?"}
  dec_pos_ligacao -- "Sim" --> res_predicativa["Oração Subordinada Substantiva Predicativa"]
  dec_pos_ligacao -- "Não" --> dec_apositiva{"Esclarece termo nominal com pontuação enfática?"}
  dec_apositiva -- "Sim" --> res_apositiva["Oração Subordinada Substantiva Apositiva"]
  dec_apositiva -- "Não" --> dec_alvo_regente{"A oração completa o sentido de um Nome ou de um Verbo?"}
  dec_alvo_regente -- "Completa Nome (com preposição)" --> res_completiva["Oração Subordinada Substantiva Completiva Nominal"]
  dec_alvo_regente -- "Completa Verbo" --> dec_preposicao{"O verbo regente exige preposição (VTI/VTDI) ou dispensa (VTD)?"}
  dec_preposicao -- "Sem preposição (VTD)" --> res_objetiva_direta["Oração Subordinada Substantiva Objetiva Direta"]
  dec_preposicao -- "Com preposição (VTI/VTDI)" --> res_objetiva_indireta["Oração Subordinada Substantiva Objetiva Indireta"]

flowchart TD
  start["Início: Identificar oração reduzida de gerúndio ou particípio"] --> dec_posicao{"Está imediatamente após um substantivo?"}
  dec_posicao -- "Não" --> res_nao_adjetiva_pos["Não é Adjetiva (Possível Oração Adverbial)"]
  dec_posicao -- "Sim" --> proc_parafrase["Substituir por: pronome relativo + verbo em tempo finito"]
  proc_parafrase --> dec_equivalencia{"A paráfrase é semanticamente equivalente?"}
  dec_equivalencia -- "Não" --> res_nao_adjetiva_sem["Descarte de Função Adjetiva"]
  dec_equivalencia -- "Sim" --> dec_pontuacao{"A oração está isolada por vírgula(s)?"}
  dec_pontuacao -- "Sim (com vírgula)" --> res_explicativa["Oração Subordinada Adjetiva Explicativa (Reduzida)"]
  dec_pontuacao -- "Não (sem vírgula)" --> res_restritiva["Oração Subordinada Adjetiva Restritiva (Reduzida)"]
